def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    dangerous_prev = []
    weak_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('budget', 0) < 40:
                weak_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                try:
                    b = float(bid)
                    prev_bids.append(b)
                    if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                        dangerous_prev.append(b)
                except Exception:
                    pass

    if not alive:
        return float(min(budget, 18.0))

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    pressure_bid = max(dangerous_prev) if dangerous_prev else highest_prev

    tight_supply = (supply <= 17.0)
    abundant_supply = (supply >= 23.0)
    urgent = (hp <= 3 or no_water_days >= 1)
    critical = (hp <= 2 or no_water_days >= 2)

    if critical:
        base = max(62.0, pressure_bid + 2.5)
    elif urgent:
        base = max(48.0, pressure_bid + 1.5)
    else:
        if tight_supply:
            base = max(36.0, avg_prev * 0.88, highest_prev * 0.82)
        elif abundant_supply:
            base = max(16.0, avg_prev * 0.45)
        else:
            base = max(24.0, avg_prev * 0.62)

    if weak_count >= 2 and not urgent:
        base *= 0.82

    if highest_prev >= 145.0 and hp > 3 and no_water_days == 0 and not tight_supply:
        base = min(base, 28.0)

    if day >= 8:
        if urgent:
            base += 6.0
        else:
            base += 2.0

    if budget < 60:
        base = min(base, budget * 0.72)
    elif budget < 120:
        base = min(base, budget * 0.82)
    else:
        base = min(base, budget * 0.9)

    if urgent and budget > 0:
        floor_bid = min(budget, 44.0 if hp > 2 else 58.0)
        if base < floor_bid:
            base = floor_bid

    if base < 0:
        base = 0.0

    return float(min(budget, round(base, 2)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    prev_bid_by_opp = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                bval = float(b)
                prev_bids.append(bval)
                prev_bid_by_opp[oid] = bval
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_bids[1]

    # Estimate how many water units are likely needed to avoid death pressure.
    # We don't know exact auction mechanics; we bid in proportion to urgency.
    urgency = 0.0
    if hp <= 2:
        urgency = 1.0
    elif hp <= 4:
        urgency = 0.7
    elif hp <= 6:
        urgency = 0.4
    else:
        urgency = 0.25

    # If we've already had no water days, increase urgency.
    if no_water_days >= 2:
        urgency = max(urgency, 0.9)
    elif no_water_days == 1:
        urgency = max(urgency, 0.55)

    # Supply pressure: lower supply means we should bid more to secure scarce water.
    supply_norm = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    # When supply is low (supply_norm small), scarcity high.
    scarcity = 1.0 - max(0.0, min(1.0, supply_norm))

    # Base bid target: try to slightly outbid the leader from yesterday if they were aggressive.
    # Use a small increment to avoid overpaying.
    aggressive_threshold = DAILY_SALARY * 0.85

    if highest_prev_bid >= aggressive_threshold:
        # If someone was already spending near daily salary, we match/beat but only if we are not in immediate danger.
        if hp > 3:
            target = highest_prev_bid + 3.0
        else:
            target = highest_prev_bid + 8.0
    else:
        # Otherwise, bid around a scarcity-adjusted fraction of daily salary.
        # Aim to beat mediocre bids without chasing the top aggressively.
        target = DAILY_SALARY * (0.45 + 0.35 * scarcity + 0.25 * urgency)

        # If yesterday had a non-trivial leader, bias upward slightly toward it.
        if highest_prev_bid > 0:
            target = max(target, min(highest_prev_bid + 2.0, highest_prev_bid * 1.08))

    # Safety cap: never exceed budget.
    # Also avoid bidding too high relative to daily salary unless urgency is high.
    max_reasonable = DAILY_SALARY * (0.95 if urgency >= 0.8 else 0.75)
    target = min(target, max_reasonable)

    # Final bid
    bid = min(budget, max(0.0, float(target)))

    # If we are very low HP or already missing water, ensure we bid close to daily salary.
    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, DAILY_SALARY * 0.95)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_players = len(alive_opponents) + 1

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 70

    if supply < (num_players * WATER_REQ) * 0.8:
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.9, avg_prev * 1.1))
    elif my_status['hp'] < 4:
        bid = min(my_status['budget'], DAILY_SALARY * 0.75)
    else:
        bid = min(my_status['budget'], max(DAILY_SALARY * 0.4, avg_prev * 0.95))

    return float(bid)
